MOD = 998244353
INV2 = (MOD + 1) // 2


def fwt_or(a, invert=False):
    """FWT 或卷积(原地)。invert 为 True 时做逆变换(除以 n 由调用方处理)."""
    n = len(a)
    h = 1
    while h < n:
        for i in range(0, n, h * 2):
            for j in range(i, i + h):
                x = a[j]
                y = a[j + h]
                if not invert:
                    a[j] = (x + y) % MOD
                    a[j + h] = x
                else:
                    a[j] = y
                    a[j + h] = (x - y) % MOD
        h <<= 1
    return a


def fwt_and(a, invert=False):
    """FWT 与卷积(原地)。"""
    n = len(a)
    h = 1
    while h < n:
        for i in range(0, n, h * 2):
            for j in range(i, i + h):
                x = a[j]
                y = a[j + h]
                if not invert:
                    a[j] = y
                    a[j + h] = (x + y) % MOD
                else:
                    a[j] = (y - x) % MOD
                    a[j + h] = x
        h <<= 1
    return a


def fwt_xor(a, invert=False):
    """FWT 异或卷积(原地). 逆变换需再乘 n^-1。"""
    n = len(a)
    h = 1
    while h < n:
        for i in range(0, n, h * 2):
            for j in range(i, i + h):
                x = a[j]
                y = a[j + h]
                a[j] = (x + y) % MOD
                a[j + h] = (x - y) % MOD
                if invert:
                    a[j] = a[j] * INV2 % MOD
                    a[j + h] = a[j + h] * INV2 % MOD
        h <<= 1
    return a


def xor_convolution(a, b):
    n = 1
    need = max(len(a), len(b))
    while n < need:
        n <<= 1
    fa = a[:] + [0] * (n - len(a))
    fb = b[:] + [0] * (n - len(b))
    fwt_xor(fa)
    fwt_xor(fb)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % MOD
    fwt_xor(fa, True)
    return fa


def or_convolution(a, b):
    n = 1
    need = max(len(a), len(b))
    while n < need:
        n <<= 1
    fa = a[:] + [0] * (n - len(a))
    fb = b[:] + [0] * (n - len(b))
    fwt_or(fa)
    fwt_or(fb)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % MOD
    fwt_or(fa, True)
    return fa


def xor_naive(a, b):
    res = [0] * (max(len(a), len(b)))
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            res[i ^ j] = (res[i ^ j] + x * y) % MOD
    return res


def or_naive(a, b):
    res = [0] * (max(len(a), len(b)))
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            res[i | j] = (res[i | j] + x * y) % MOD
    return res


def and_convolution(a, b):
    n = 1
    need = max(len(a), len(b))
    while n < need:
        n <<= 1
    fa = a[:] + [0] * (n - len(a))
    fb = b[:] + [0] * (n - len(b))
    fwt_and(fa)
    fwt_and(fb)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % MOD
    fwt_and(fa, True)
    return fa


def and_naive(a, b):
    res = [0] * (max(len(a), len(b)))
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            res[i & j] = (res[i & j] + x * y) % MOD
    return res


if __name__ == "__main__":
    import random
    for _ in range(200):
        n = 1 << random.randint(1, 4)
        a = [random.randint(0, 20) for _ in range(n)]
        b = [random.randint(0, 20) for _ in range(n)]
        assert xor_convolution(a, b) == xor_naive(a, b), ("xor", a, b)
        assert or_convolution(a, b) == or_naive(a, b), ("or", a, b)
        assert and_convolution(a, b) == and_naive(a, b), ("and", a, b)
    # 手工样例: (1+x^1)(1+x^1) 的异或卷积
    assert xor_convolution([1, 1], [1, 1]) == [2, 2]
    print("FWT (and/or/xor) tests passed")
